export var NVDA_CE_CONS=(function(){
  var G=NVDA_CE_CONS_GEN, M=nvdaResults.views.q.metrics, MX=nvdaResults.estMatrix&&nvdaResults.estMatrix.cons;
  function fy(q){ return q.replace(/^Q(\d) 20(\d\d)$/, 'Q$1 FY$2'); }            // 'Q3 2027' → 'Q3 FY27' (fiscal, never read as calendar)
  var Q=G.q.map(fy);
  function pOf(q){ return q.charAt(1)+'Q'+q.slice(-2); }                        // 'Q3 FY27' → '3Q27'
  function ord(p){ var m=/^(\d)Q(\d{2})$/.exec(p); return m?(2000+(+m[2]))*4+(+m[1]):null; }
  function rnd(v,u){ if(v==null) return null; if(u==='$') return Math.round(v*100)/100; if(u==='Mn') return Math.round(v); return Math.round(v*1000)/1000; }
  var byK={};
  // 1 · the generated lines: $M → $B (shares stay in millions)
  G.m.forEach(function(o){
    var shares=(o.u==='M'), u=shares?'Mn':'$B', dv=shares?1:1000;
    byK[o.k]={ k:o.k, u:u, qa:o.qa.map(function(v){ return rnd(v==null?null:v/dv,u); }), qr:o.qr.map(function(r){ return r.map(function(v){ return rnd(v==null?null:v/dv,u); }); }) }; });
  // 1b · reported actuals the archive does not have yet (BBG refresh pending), from the 8-K — see ACT_8K above.
  Object.keys(ACT_8K).forEach(function(q){ var i=Q.indexOf(q); if(i<0) return; var row=ACT_8K[q];
    Object.keys(row).forEach(function(k){ var o=byK[k]; if(!o||o.qa[i]!=null) return; var shares=(o.u==='Mn');
      o.qa[i]=rnd(row[k]==null?null:(shares?row[k]:row[k]/1000), o.u); }); });
  // 2 · the Results lines: actual + each horizon's latest Bloomberg vintage (estMatrix), as in tbbb-ce-data.js
  FROM_RESULTS.forEach(function(x){
    var r=M[x[1]]; if(!r) return; var u=x[2], dv=(u==='$')?1:1000, rows=MX&&MX.q&&MX.q[x[1]];
    function at(arr,p){ var i=r.periods.indexOf(p); return (i<0||!arr||arr[i]==null)?null:arr[i]/dv; }
    byK[x[0]]={ k:x[0], u:u,
      qa:Q.map(function(q){ return rnd(at(r.act,pOf(q)),u); }),
      qr:Q.map(function(q){
        var p=pOf(q), op=ord(p), row=[null,null,null,at(r.cons,p)];
        if(rows) MX.vintages.forEach(function(v){   // oldest → newest, so the latest vintage at each horizon wins
          var h=op-ord(v.lastActual.q); if(h<1||h>4) return; var c=rows[v.id]&&rows[v.id][p]; if(c!=null) row[4-h]=c/dv; });
        return row.map(function(v){ return rnd(v,u); }); }) }; });
  // a quarter two out: the newest file's value stands in the "1q out" column (the portal shows two quarters ahead)
  Object.keys(byK).forEach(function(k){ var o=byK[k]; Q.forEach(function(q,i){
    if(o.qa[i]!=null || o.qr[i][3]!=null) return; for(var h=2; h>=0; h--){ if(o.qr[i][h]!=null){ o.qr[i][3]=o.qr[i][h]; break; } } }); });
  var CUSTOM=['Data Center','Hyperscale','AI Clouds, Industrial & Enterprise','Data Center compute','Data Center networking','Edge Computing',
    'Research & development','Sales, general & administrative','Operating expenses','Operating income (GAAP)','Compute & Networking op. income','Graphics op. income',
    'Interest income','Income tax','Net income (GAAP)','Free cash flow'];
  var m=NHEAD.concat(CUSTOM).filter(function(k){ return byK[k]; }).map(function(k){
    var o=byK[k], anyA=o.qa.some(function(v){ return v!=null; }), anyC=o.qr.some(function(r){ return r.some(function(v){ return v!=null; }); });
    o.t=(anyA&&!anyC)?'nocons':((anyC&&!anyA)?'noact':'ok');
    o.qy=Q.map(function(q,i){ return i>=4?o.qa[i-4]:null; }); o.qq=Q.map(function(q,i){ return i>=1?o.qa[i-1]:null; });
    return o; });
  return { src:'Bloomberg (BST) · BBG_CONSENSUS.txt ('+G.asOf.length+' NVIDIA snapshots, newest '+G.asOf[G.asOf.length-1]+') · reported lines from js/results-data/nvda.js',
    asOf:G.asOf, q:Q, hz:['4q out','3q out','2q out','1q out'], nHead:NHEAD.length, m:m };
})();

// Summit for a quarter's Setup (`setup.us`): READ from the Results dataset — each quarter carries the model as frozen at its latest
// submit BEFORE that print (2Q FY27: 2026-03-04; 3Q and 4Q FY27: 2026-08-28). The model projects revenue, Data Center, gross profit
// and operating income (both bases) by quarter; every other line reads "—".
var FROM_SUMMIT=[['Revenue','rev'],['Data Center','dc'],['Gross profit','gp'],['Operating income','opinc_ng'],['Operating income (GAAP)','opinc']];
function ceSummitUs(p){
  var M=nvdaResults.views.q.metrics, out={};
  FROM_SUMMIT.forEach(function(x){ var r=M[x[1]], i=r?r.periods.indexOf(p):-1, v=(i>=0&&r.summit)?r.summit[i]:null;
    if(v!=null) out[x[0]]={ v:Math.round(v)/1000 }; });
  return out;
}

